describe('Public Profile Page - Shared Information Display', () => {
  beforeEach(() => {
    cy.visit('/profile/user123');
  });

  it('should display public profile with shared information', () => {
    // Verify profile page loads
    cy.get('[data-testid="profile-container"]').should('be.visible');

    // Verify user name is displayed
    cy.get('[data-testid="profile-name"]').should('contain', 'John Doe');

    // Verify bio is displayed
    cy.get('[data-testid="profile-bio"]').should('be.visible').should('contain', 'Software engineer passionate about Cypress');

    // Verify location is displayed
    cy.get('[data-testid="profile-location"]').should('be.visible').should('contain', 'San Francisco, CA');

    // Verify website link is displayed
    cy.get('[data-testid="profile-website"]').should('be.visible').should('contain', 'john-doe.dev');

    // Verify follower count is displayed
    cy.get('[data-testid="profile-followers"]').should('be.visible').should('contain', '1,4k');

    // Verify following count is displayed
    cy.get('[data-testid="profile-following"]').should('be.visible').should('contain', '25');

    // Verify profile picture is displayed
    cy.get('[data-testid="profile-picture"]').should('be.visible').should('have.attr', 'src');

    // Verify public profile badge is visible
    cy.get('[data-testid="public-profile-badge"]').should('be.visible');
  });

  it('should handle missing or incomplete shared information gracefully', () => {
    // Navigate to a profile with minimal shared info
    cy.visit('/profile/user44');

    // Verify profile container still loads
    cy.get('[data-testid="profile-container"]').should('be.visible');

    // Verify name is displayed even if bio is missing
    cy.get('[data-testid="profile-name"]').should('contain', 'Jane Smith');

    // Verify bio placeholder or empty state is shown
    cy.get('[data-testid="profile-bio"]').should('be.visible').should('contain', 'No bio available');

    // Verify location is displayed
    cy.get('[data-testid="profile-location"]').should('be.visible').should('contain', 'Remote');

    // Verify website link is not displayed if not shared
    cy.get('[data-testid="profile-website"]').should('not.exist');

    // Verify follower count is displayed
    cy.get('[data-testid="profile-followers"]').should('be.visible').should('contain', '1');

    // Verify error message for missing profile is not shown
    cy.get('[data-testid="profile-error-message"]').should('not.exist');
  });
});
